<template>
 <view class="conflict-overlay" @click.self="close" @keydown.esc.stop="close"><view ref="dialog" class="conflict-dialog" role="dialog" aria-modal="true" aria-label="已有招募，选择处理" tabindex="-1" @keydown.tab="trapFocus">
  <app-toast :message="errorToast" type="error"/>
  <view class="conflict-head"><view><b>你已有一条正在进行的招募</b><text>本次填写的信息尚未发布</text><view class="replace-note" :class="{blocked:!canReplace}">{{canReplace?'重新招募将结束原招募，按本次条件重新计时 20 分钟；原分享链接将失效':blockedMessage}}</view></view><button tabindex="0" class="close" aria-label="关闭招募对比" :disabled="busy" @click="close">×</button></view>
  <view class="conflict-body"><view class="comparison-header"><text>项目</text><text>正在招募</text><text>本次填写</text></view><view v-for="row in rows" :key="row.key" class="comparison-row" :class="{changed:row.changed}"><view class="row-label">{{row.label}}<text v-if="row.changed">有变化</text></view><view class="comparison-cell"><text v-for="(value,index) in row.old" :key="index">{{value}}</text><text v-if="!row.old.length">未填写</text></view><view class="comparison-cell new-values"><text v-for="(value,index) in row.next" :key="index">{{value}}</text><text v-if="!row.next.length">未填写</text></view></view>
  </view>
  <view class="conflict-footer"><view class="main-actions"><button tabindex="0" class="primary" :disabled="busy||!canReplace" @click="$emit('replace')">{{busy?'正在提交…':'使用本次条件重新招募'}}</button><button tabindex="0" class="secondary" :disabled="busy" @click="$emit('view')">保留已有招募并查看进度</button></view><view class="footer-secondary"><button tabindex="0" class="continue" :disabled="busy" @click="close">继续编辑</button><text class="draft-note">本次填写保留为草稿</text></view></view>
 </view></view>
</template>
<script setup>
import {ref,watch,nextTick,onMounted,onBeforeUnmount} from 'vue'
import AppToast from './app-toast.vue'
const props=defineProps({rows:{type:Array,default:()=>[]},busy:Boolean,canReplace:Boolean,blockedMessage:String,error:String})
const emit=defineEmits(['close','view','replace'])
const dialog=ref(null),errorToast=ref('')
let lastFocus=null,bodyOverflow='',rootOverflow='',timer=null
const element=()=>dialog.value?.$el||dialog.value
function close(){if(!props.busy)emit('close')}
watch(()=>props.error,message=>{if(!message)return;clearTimeout(timer);errorToast.value=message;timer=setTimeout(()=>{errorToast.value=''},6000)})
onMounted(async()=>{if(typeof document==='undefined')return;lastFocus=document.activeElement;bodyOverflow=document.body.style.overflow;rootOverflow=document.documentElement.style.overflow;document.body.style.overflow='hidden';document.documentElement.style.overflow='hidden';await nextTick();element()?.focus()})
onBeforeUnmount(()=>{clearTimeout(timer);if(typeof document!=='undefined'){document.body.style.overflow=bodyOverflow;document.documentElement.style.overflow=rootOverflow;lastFocus?.focus?.()}})
function trapFocus(event){const nodes=[...element().querySelectorAll('[tabindex="0"]')].filter(node=>!node.hasAttribute('disabled'));if(!nodes.length){event.preventDefault();return}const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===element())){event.preventDefault();last.focus()}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===element())){event.preventDefault();first.focus()}}
</script>
<style scoped>
.conflict-overlay{position:fixed;inset:0;z-index:100;background:#03070bdb;backdrop-filter:blur(7px);display:flex;align-items:center;justify-content:center;padding:20px}.conflict-dialog{width:100%;max-width:740px;max-height:88vh;display:flex;flex-direction:column;background:#141e2b;border:1px solid #42536c;border-radius:14px;box-shadow:0 25px 90px #0009;color:#d5e1ef;outline:none}.conflict-head{padding:19px 22px;display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #2d3b4e}.conflict-head b{display:block;font-size:17px}.conflict-head text{display:block;margin-top:7px;color:#9aacbf;font-size:11px}.close{margin:0;padding:0 4px;border:0;background:none;color:#9aacbf;font-size:24px;line-height:1}.conflict-body{overflow-y:auto;min-height:0;overscroll-behavior:contain;padding:15px 22px}.comparison-header,.comparison-row{display:grid;grid-template-columns:90px minmax(0,1fr) minmax(0,1fr);gap:12px}.comparison-header{font-size:11px;color:#93a8c0;padding-bottom:10px}.comparison-header>text:last-child{color:#bfe4a1}.comparison-row{padding:11px 0;border-top:1px solid #28384b;font-size:11px;align-items:start}.row-label{color:#96aac2;line-height:1.8}.row-label>text{display:block;font-size:9px;color:#e9c282}.comparison-cell{display:flex;flex-wrap:wrap;align-content:flex-start;gap:5px;min-width:0}.comparison-cell>text{line-height:1.7;padding:2px 6px;border:1px solid #34465b;background:#0f1925;color:#bbcadb;border-radius:4px;overflow-wrap:anywhere}.changed .new-values>text{background:#b9f4770d;border-color:#607e49;color:#c9e8af}.replace-note{font-size:11px;line-height:1.8;color:#9eafc4;margin-top:16px;padding-top:12px;border-top:1px solid #2d3b4e}.replace-note.blocked{color:#e9c282}.conflict-footer{padding:15px 22px;border-top:1px solid #2d3b4e;background:#111b27;border-radius:0 0 14px 14px}.main-actions{display:flex;gap:10px}.main-actions button{margin:0;flex:1;padding:10px 13px;font-size:12px;line-height:1.5;border-radius:7px;border:1px solid #415771;color:#c3d3e4;background:#1b2939}.main-actions .primary{background:#b9f477;border-color:#b9f477;color:#17250c;font-weight:650}.continue{display:inline-flex;background:transparent;border:0;color:#9db0c9;font-size:11px;margin:9px 12px 0 0;padding:3px 0;line-height:1.6}.draft-note{font-size:10px;color:#7e92ab}button[disabled]{opacity:.4;cursor:not-allowed}button:focus-visible{outline:2px solid #b9f477;outline-offset:3px}@media(max-width:520px){.conflict-overlay{padding:12px}.conflict-head,.conflict-body,.conflict-footer{padding:15px}.conflict-head b{font-size:15px}.comparison-header,.comparison-row{grid-template-columns:64px minmax(0,1fr) minmax(0,1fr);gap:7px}.comparison-cell>text{padding:2px 4px;font-size:10px}.main-actions{flex-direction:column;gap:8px}.conflict-dialog{max-height:90vh}}
.conflict-dialog{overflow:hidden}.conflict-head,.conflict-footer{flex-shrink:0}.conflict-body{flex:1 1 auto}.conflict-head .replace-note{color:#efc17d;font-size:11px;font-weight:500;line-height:1.8;margin-top:9px;padding:0;border:0}.conflict-head .replace-note.blocked{color:#f1a6a6}.footer-secondary{display:flex;align-items:center;gap:12px;margin-top:11px}.footer-secondary .continue{display:inline-flex;justify-content:center;align-items:center;min-height:36px;box-sizing:border-box;margin:0;padding:7px 16px;border:1px solid #647d50;border-radius:7px;background:#b9f4770c;color:#d1e6bc;font-size:12px;font-weight:550;line-height:1.5;white-space:nowrap}.footer-secondary .continue:hover{background:#b9f47718;border-color:#a0c477}.footer-secondary .draft-note{color:#96aac2}
</style>
